import React, { useState, useEffect } from 'react';
import { anyObject } from '../../../../common_types/object';
import { Link, useParams } from 'react-router-dom';
import axios from 'axios';
import moment from 'moment/moment';
import BackButton from '../../../components/BackButton';
export interface Props {}

const Section: React.FC<Props> = (props: Props) => {
    const [error, setError] = useState(null);
    const [data, setData] = useState([]);
    const { id } = useParams();

    useEffect(() => {
        // Function to fetch data
    }, []);

    const fetchData = async () => {
        try {
            const response = await axios.get(
                `/api/v1/branch-class-sections/class-wise/${id}`,
            );
            setData(response.data.data);
            // setData(response.data);
        } catch (error) {
            setError(error);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);
    console.log(data);

    return (
        <div className="admin_dashboard">
            <div className="dues_back_btn">
                <h3 className="table_heading"></h3>
                {/* <button className="back_btn settings_bacsk">
                </button> */}
                <BackButton></BackButton>
            </div>
            <div className="content_body">
                <div className="data_list">
                    <div className="table_responsive custom_scroll">
                        <table>
                            <thead>
                                <tr>
                                    <th></th>
                                    <th>Serial</th>
                                    <th>Section</th>
                                    {/* <th>Subject</th> */}
                                    {/* <th>Total Student</th> */}
                                    <th>Action</th>
                                </tr>
                            </thead>
                            <tbody id="all_list">
                                {data?.map(
                                    (i: { [key: string]: any }, index) => {
                                        return (
                                            <tr>
                                                <td></td>
                                                <td>{index + 1}</td>
                                                <td>{i.title}</td>
                                                {/* <td>{i.subject}</td> */}
                                                {/* <td>{i.count}</td> */}
                                                <td>
                                                    {/* <Link
                                                        className="btn btn-sm btn-outline-info mr-1"
                                                        to={`/class-attendance/section/${i.id}?c_id=${id}`}
                                                    >
                                                        Details
                                                    </Link> */}
                                                    <Link
                                                        className="btn btn-sm btn-outline-info mr-1"
                                                        to={`/user-students/class-details/${id}?sec_id=${i.id}`}
                                                    >
                                                        Details
                                                    </Link>
                                                </td>
                                            </tr>
                                        );
                                    },
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Section;
